"""Path31 — RaptorX v1: OUR whole-volume conv-attention arm.

Original work, end to end: our slot-quota volume layout (32 slices routed
across the 5 audited slots), contiguous 3-slice windows, our per-target
attention-MIL head, CoAtNet backbone fine-tuned on OUR fused silver labels
(v6, gold macro 0.9006) with full-gold lambda=2, scanner-grouped fold-0
holdout for the honest read, SWA over the closing epochs. The public
frontier's equivalent arm ships as a black-box checkpoint with no training
code — this one is ours.

Internet is ON for the timm pretrained download only; this kernel never
produces a competition submission itself (checkpoint + metrics + a ranked
test CSV for later fusion kernels).
"""

from __future__ import annotations

import base64
import gc
import importlib.util
import json
import math
import os
import random
import time
from pathlib import Path

import numpy as np
import pandas as pd

T0 = time.time()
SEED = 20260902
IMG = 224
VOL_SLICES = 32
WINDOW = 3
STRIDE = 2
SLOT_QUOTAS = [10, 7, 6, 5, 4]          # SAG_FLUID, COR_FLUID, AX_FLUID, SAG_STRUCT, COR_STRUCT
VOL_BAND = (0.06, 0.94)
CROP_MM = 140.0
BATCH_STUDIES = 2
EVAL_BATCH = 2
EPOCHS = 12
LR_BACKBONE = 2.5e-5
LR_HEAD = 5.0e-4
WEIGHT_DECAY = 0.01
GOLD_LAMBDA = 2.0
SWA_LAST = 3
TIME_LIMIT_S = 10.5 * 3600
EPOCH_DEADLINE_S = 9.3 * 3600           # no new epoch after this
MEMBER_TAG = "raptorx1"
BACKBONES = [
    "coatnet_rmlp_1_rw2_224.sw_in12k_ft_in1k",
    "coatnet_rmlp_1_rw_224.sw_in1k",
    "coatnet_1_rw_224.sw_in1k",
]

P27_B64 = ""


def log(msg):
    print(f"[p31 {time.time() - T0:7.1f}s] {msg}", flush=True)


def load_p27():
    path = Path("p31_p27mod.py")
    path.write_bytes(base64.b64decode(P27_B64))
    spec = importlib.util.spec_from_file_location("p27mod", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def read_slot_n(mod, record, n_slices, side, plane):
    """Decode n_slices evenly across VOL_BAND of one series at CROP_MM/IMG.
    Borrow p27's ordering; own decode so the count is parameterisable."""
    import pydicom
    import torch
    import torch.nn.functional as F

    files = mod.ordered_files(record)
    count = len(files)
    lo = int(VOL_BAND[0] * (count - 1))
    hi = int(VOL_BAND[1] * (count - 1))
    idx = np.linspace(lo, max(lo, hi), n_slices).round().astype(int)
    images, spacing = [], None
    for i in idx:
        try:
            ds = pydicom.dcmread(os.path.join(record["dir"], files[int(i)]), force=True)
            img = ds.pixel_array.astype(np.float32)
            img = img * float(getattr(ds, "RescaleSlope", 1) or 1) + float(getattr(ds, "RescaleIntercept", 0) or 0)
            sp = getattr(ds, "PixelSpacing", None)
            if sp is not None:
                spacing = float(sp[0])
            images.append(img)
        except Exception:
            images.append(None)
    good = [i for i, im in enumerate(images) if im is not None]
    if not good:
        return None
    for i, im in enumerate(images):
        if im is None:
            images[i] = images[min(good, key=lambda j: abs(j - i))]
    shape = images[0].shape
    images = [im if im.shape == shape else np.zeros(shape, np.float32) for im in images]
    vol = np.stack(images)
    if spacing and np.isfinite(spacing) and spacing > 0:
        want = int(round(CROP_MM / spacing))
        h, w = shape
        if 16 < want < min(h, w):
            cy, cx = h // 2, w // 2
            half = want // 2
            vol = vol[:, cy - half:cy + half, cx - half:cx + half]
    lo_v, hi_v = np.percentile(vol, [1, 99])
    vol = np.clip((vol - lo_v) / max(hi_v - lo_v, 1e-6), 0, 1)
    import torch
    t = torch.from_numpy(np.ascontiguousarray(vol)).unsqueeze(0)
    t = F.interpolate(t, (IMG, IMG), mode="bilinear", align_corners=False)
    out = (t.squeeze(0) * 255).round().clamp(0, 255).to(torch.uint8).numpy()
    if side == "R":
        if plane in ("Coronal", "Axial"):
            out = out[:, :, ::-1].copy()
        elif plane == "Sagittal":
            out = out[::-1].copy()
    return out


def build_volume_cache(mod, slot_map, sides, tag):
    from concurrent.futures import ThreadPoolExecutor

    studies = sorted(slot_map)
    index = {s: i for i, s in enumerate(studies)}
    cache = np.zeros((len(studies), VOL_SLICES, IMG, IMG), dtype=np.uint8)
    filled = np.zeros(len(studies), dtype=np.int32)

    def job(item):
        study, slots = item
        parts = []
        for slot_i, record in enumerate(slots):
            if record is None:
                continue
            block = read_slot_n(mod, record, SLOT_QUOTAS[slot_i], sides.get(study),
                                mod.SLOTS[slot_i][1])
            if block is not None:
                parts.append(block)
        if not parts:
            return study, None
        vol = np.concatenate(parts, axis=0)
        if len(vol) < VOL_SLICES:  # repeat-fill missing slots' quota
            reps = int(np.ceil(VOL_SLICES / len(vol)))
            vol = np.concatenate([vol] * reps, axis=0)
        return study, vol[:VOL_SLICES]

    with ThreadPoolExecutor(max_workers=10) as pool:
        for done, (study, vol) in enumerate(pool.map(job, slot_map.items()), 1):
            if vol is not None:
                cache[index[study]] = vol
                filled[index[study]] = 1
            if done % 500 == 0:
                log(f"{tag}: cached {done}/{len(studies)}")
            if time.time() - T0 > TIME_LIMIT_S:
                raise TimeoutError("time budget exhausted during volume caching")
    if not filled.all():
        raise RuntimeError(f"{tag}: {int((1 - filled).sum())} studies produced no volume")
    log(f"{tag}: volume cache {cache.nbytes / 1024**3:.2f} GiB")
    return studies, cache


def window_stack(vols_u8, device):
    """(B, VOL_SLICES, H, W) uint8 -> (B, K, 3, H, W) float on device."""
    import torch

    x = torch.from_numpy(vols_u8).to(device).float().div_(255.0)
    centers = list(range(1, VOL_SLICES - 1, STRIDE))
    wins = torch.stack([x[:, c - 1:c + 2] for c in centers], dim=1)
    return wins, len(centers)


class RaptorX:
    """CoAtNet windows + per-target attention-MIL head (ours)."""

    def __init__(self, device):
        import timm
        import torch
        import torch.nn as nn

        last_err = None
        for name in BACKBONES:
            try:
                self.backbone = timm.create_model(name, pretrained=True, num_classes=0)
                self.name = name
                break
            except Exception as exc:      # model name drift across timm versions
                last_err = exc
        else:
            raise RuntimeError(f"no CoAtNet backbone could be created: {last_err}")
        dim = self.backbone.num_features
        self.norm = nn.LayerNorm(dim)
        self.att = nn.Linear(dim, 12)
        self.cls = nn.Linear(dim, 12)
        self.modules_ = nn.ModuleDict({
            "backbone": self.backbone, "norm": self.norm,
            "att": self.att, "cls": self.cls,
        }).to(device)
        mean = torch.tensor([0.485, 0.456, 0.406]).view(1, 3, 1, 1).to(device)
        std = torch.tensor([0.229, 0.224, 0.225]).view(1, 3, 1, 1).to(device)
        self.mean, self.std = mean, std
        n = sum(p.numel() for p in self.modules_.parameters())
        log(f"backbone={self.name} dim={dim} params={n/1e6:.1f}M")

    def forward(self, wins):
        import torch
        B, K = wins.shape[:2]
        flat = wins.reshape(B * K, *wins.shape[2:])
        flat = (flat - self.mean) / self.std
        feats = self.backbone(flat).reshape(B, K, -1)
        h = self.norm(feats)
        att = torch.softmax(self.att(h), dim=1)            # (B, K, 12) over windows
        cls = self.cls(h)                                   # (B, K, 12)
        return (att * cls).sum(dim=1)                       # (B, 12)

    def parameters_groups(self):
        head = list(self.norm.parameters()) + list(self.att.parameters()) + list(self.cls.parameters())
        return [
            {"params": self.backbone.parameters(), "lr": LR_BACKBONE},
            {"params": head, "lr": LR_HEAD},
        ]


def augment(wins):
    import torch
    B, K, C, H, W = wins.shape
    flat = wins.reshape(B * K, C, H, W)
    gain = 0.92 + torch.rand(B * K, 1, 1, 1, device=flat.device) * 0.16
    bias = (torch.rand(B * K, 1, 1, 1, device=flat.device) - 0.5) * 0.06
    flat = (flat * gain + bias).clamp(0, 1)
    if torch.rand(()) < 0.5:
        shift = int(torch.randint(-8, 9, ()).item())
        flat = torch.roll(flat, shifts=(shift,), dims=(-1,))
    return flat.reshape(B, K, C, H, W)


def main():
    import torch
    import torch.nn.functional as F

    random.seed(SEED)
    np.random.seed(SEED)
    torch.manual_seed(SEED)
    torch.cuda.manual_seed_all(SEED)

    mod = load_p27()
    root = mod.find_competition_root()
    label_path = mod.find_labels()
    train_df = pd.read_csv(root / "train.csv")
    labels = mod.validate_and_join_labels(train_df, label_path)
    keep = set(labels["StudyInstanceUID"])

    series_csv = pd.read_csv(root / "train_series.csv")
    series = mod.list_series(root / "train_series", series_csv, keep)
    slots = mod.choose_slots(series)
    headers, probes = mod.study_headers(slots)
    sides = mod.laterality_map(probes)
    groups = mod.scanner_groups(headers)
    studies, cache = build_volume_cache(mod, slots, sides, "train")

    device = torch.device("cuda")
    table, train_idx, val_idx, gold_idx, _ = mod.make_clean_split(studies, labels, groups, 0)
    targets = table[mod.TARGETS].values.astype(np.float32)
    conf = 0.25 + 0.75 * np.abs(targets - 0.5) * 2.0
    gold_cols = [f"{t}__gold" for t in mod.TARGETS]
    gold_truth = table[gold_cols].values.astype(np.float32)
    targets = targets.copy()
    conf = conf.copy()
    targets[gold_idx] = gold_truth[gold_idx]
    conf[gold_idx] *= GOLD_LAMBDA
    full_train = np.concatenate([train_idx, gold_idx])
    log(f"train={len(train_idx)} +gold={len(gold_idx)}, holdout={len(val_idx)} (scanner fold 0)")

    model = RaptorX(device)
    optimizer = torch.optim.AdamW(model.parameters_groups(), weight_decay=WEIGHT_DECAY)
    steps = max(1, len(full_train) // BATCH_STUDIES)
    scheduler = torch.optim.lr_scheduler.OneCycleLR(
        optimizer, max_lr=[LR_BACKBONE, LR_HEAD], total_steps=steps * EPOCHS, pct_start=0.1)
    scaler = torch.amp.GradScaler("cuda")

    def predict(indices):
        model.modules_.eval()
        outs = []
        with torch.no_grad():
            for s in range(0, len(indices), EVAL_BATCH):
                sel = indices[s:s + EVAL_BATCH]
                wins, _ = window_stack(cache[sel], device)
                with torch.autocast("cuda"):
                    logits = model.forward(wins)
                outs.append(torch.sigmoid(logits).float().cpu().numpy())
        return np.concatenate(outs)

    history = []
    swa_states = []
    for epoch in range(EPOCHS):
        if epoch > 0 and time.time() - T0 > EPOCH_DEADLINE_S:
            log(f"epoch {epoch}: deadline passed, stopping training loop")
            break
        model.modules_.train()
        perm = np.random.permutation(full_train)
        losses = []
        for s in range(0, len(perm) - BATCH_STUDIES + 1, BATCH_STUDIES):
            sel = perm[s:s + BATCH_STUDIES]
            wins, _ = window_stack(cache[sel], device)
            wins = augment(wins)
            truth = torch.from_numpy(targets[sel]).to(device)
            weight = torch.from_numpy(conf[sel]).to(device)
            optimizer.zero_grad(set_to_none=True)
            with torch.autocast("cuda"):
                logits = model.forward(wins)
                cell = F.binary_cross_entropy_with_logits(logits, truth, reduction="none")
                loss = (cell * weight).sum() / weight.sum().clamp_min(1)
            scaler.scale(loss).backward()
            scaler.step(optimizer)
            scaler.update()
            scheduler.step()
            losses.append(float(loss.detach().cpu()))
            if time.time() - T0 > TIME_LIMIT_S:
                raise TimeoutError("time budget exhausted mid-epoch")
        val_pred = predict(val_idx)
        auc, per_t = mod.macro_auc((targets[val_idx] > 0.5).astype(int), val_pred)
        history.append({"epoch": epoch + 1, "loss": float(np.mean(losses)),
                        "holdout_auc": auc, "per_target": per_t})
        log(f"epoch {epoch+1}/{EPOCHS}: loss={np.mean(losses):.4f} holdout={auc:.4f}")
        swa_states.append({k: v.detach().cpu().clone() for k, v in model.modules_.state_dict().items()})
        swa_states = swa_states[-SWA_LAST:]  # SWA = last <=3 completed epochs, early-stop safe

    if not swa_states:
        raise RuntimeError("no epochs completed")
    avg = {k: sum(s[k].float() for s in swa_states) / len(swa_states) for k in swa_states[-1]}
    model.modules_.load_state_dict({k: v.to(swa_states[-1][k].dtype) for k, v in avg.items()})
    val_pred = predict(val_idx)
    swa_auc, swa_per_t = mod.macro_auc((targets[val_idx] > 0.5).astype(int), val_pred)
    log(f"SWA({len(swa_states)}): holdout={swa_auc:.4f}")

    torch.save({
        "state_dict": model.modules_.state_dict(),
        "backbone": model.name,
        "img": IMG, "vol_slices": VOL_SLICES, "window": WINDOW, "stride": STRIDE,
        "slot_quotas": SLOT_QUOTAS, "vol_band": VOL_BAND, "crop_mm": CROP_MM,
        "targets": mod.TARGETS, "member_tag": MEMBER_TAG,
        "gold_training_count": int(len(gold_idx)), "gold_lambda": GOLD_LAMBDA,
        "label_source": mod.LABELS_FILE, "holdout_fold": 0,
    }, f"{MEMBER_TAG}_swa.pt")

    hold = pd.DataFrame(val_pred, columns=mod.TARGETS)
    hold.insert(0, "StudyInstanceUID", [studies[i] for i in val_idx])
    hold.to_csv(f"{MEMBER_TAG}_holdout.csv", index=False)

    test_df = pd.read_csv(root / "test.csv")
    t_series = mod.list_series(root / "test_series", pd.read_csv(root / "test_series.csv"),
                               set(test_df["StudyInstanceUID"]))
    t_slots = mod.choose_slots(t_series)
    t_headers, t_probes = mod.study_headers(t_slots)
    t_sides = mod.laterality_map(t_probes)
    t_studies, t_cache = build_volume_cache(mod, t_slots, t_sides, "test")
    cache = t_cache  # predict() closes over `cache`
    t_pred = predict(np.arange(len(t_studies)))
    sub = pd.DataFrame(mod.rank_predictions(t_pred), columns=mod.TARGETS)
    sub.insert(0, "StudyInstanceUID", t_studies)
    sub.to_csv(f"{MEMBER_TAG}_test.csv", index=False)

    Path("metrics.json").write_text(json.dumps({
        "member": MEMBER_TAG, "backbone": model.name, "img": IMG,
        "vol_slices": VOL_SLICES, "slot_quotas": SLOT_QUOTAS,
        "epochs_completed": len(history), "history": history,
        "holdout_macro_auc_swa": float(swa_auc),
        "holdout_per_target_swa": swa_per_t,
        "label_source": mod.LABELS_FILE,
        "gold_usage": "full (lambda=2 training); holdout is scanner fold 0, gold-free",
        "elapsed_seconds": time.time() - T0,
    }, indent=2))
    log(f"done in {(time.time() - T0)/3600:.2f}h — SWA holdout {swa_auc:.4f}")


if __name__ == "__main__":
    main()
